var o=`0598-boortsog`;var n=`world-0598`;var i=`MN`;var t=`east-asia`;var l=8;var r=81;var s={en:`Boortsog`,ua:`Боорцог`};var u={en:`A traditional dish from Mongolia, centered on all-purpose flour, whole cow milk, instant yeast. A measured home-kitchen version organized by cooking step.`,ua:`Традиційна страва кухні країни Монголія. Основні складники: пшеничне борошно універсальне, цільне коров'яче молоко, інстантні дріжджі. Домашній варіант із кількостями продуктів за етапами приготування.`};var d=[{en:`Mix and knead into a supple yeast dough. Cover and leave in a warm place until roughly doubled, about 55 minutes.`,ua:`Змішайте й вимісіть м’яке дріжджове тісто. Накрийте та поставте в тепле місце до збільшення об’єму приблизно вдвічі, орієнтовно на 55 хвилин.`,t:[`mixing`,`kneading`,`bulk-fermentation`],m:55,i:[[`all-purpose-flour`,450,`g`],[`whole-cow-milk`,180,`ml`],[`water`,100,`ml`],[`instant-yeast`,7,`g`],[`white-granulated-sugar`,45,`g`]]},{en:`Divide and shape the dough as required. Place on a lined tray and proof for about 12 minutes while the oven heats.`,ua:`Поділіть і сформуйте тісто відповідно до виробу. Викладіть на деко з пергаментом і залиште підходити приблизно на 12 хвилин, поки гріється духовка.`,t:[`pre-shaping-dough`,`final-proofing`],m:12,i:[]},{en:`Fry shaped portions in small batches in oil heated to about 170–175°C for about 14 minutes, until golden; drain on a rack.`,ua:`Смажте сформовані вироби невеликими партіями в олії температурою приблизно 170–175°C близько 14 хвилин до золотистості; викладіть на решітку.`,t:[`deep-frying`],m:14,i:[[`sunflower-oil`,700,`ml`]]}];var g={slug:o,id:n,country:`MN`,region:t,servings:8,minutes:81,title:s,text:u,steps:d};export{i as country,g as default,n as id,r as minutes,t as region,l as servings,o as slug,d as steps,u as text,s as title};